import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 extraAmount) public {
        // Keep amounts within admissible range
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(extraAmount < 1000 ether);

        // Ensure owner has enough Ether to send deposits
        vm.deal(c.owner(), depositAmount + extraAmount);
        vm.prank(c.owner());

        // Record initial contract balance before deposits
        uint256 initialBal = address(c).balance;

        // Make deposits to the contract by sending Ether to trigger fallback
        vm.prank(c.owner());
        (bool s,) = address(c).call{value: depositAmount}("");
        require(s, "deposit failed");

        // Also send extraAmount via sendMoney to simulate additional balance
        if (extraAmount > 0) {
            vm.prank(c.owner());
            c.sendMoney{value: extraAmount}(address(c), extraAmount, "");
        }

        uint256 contractBalBefore = address(c).balance;
        require(contractBalBefore > 0, "contract must have balance");

        uint256 ownerBalBefore = c.owner().balance;

        // Now call withdrawAll
        vm.prank(c.owner());
        c.withdrawAll();

        uint256 contractBalAfter = address(c).balance;
        uint256 ownerBalAfter = c.owner().balance;

        // Invariant: after withdrawAll, the contract's balance must be 0
        // and the owner's balance must have increased by the contract's prior balance.
        // Reference satisfies this; the buggy version leaves contract balance non-zero
        // because it transfers 0 instead of the full balance.
        assertTrue(
            contractBalAfter == 0 &&
            ownerBalAfter == ownerBalBefore + contractBalBefore
        );
    }
}

